INSERT INTO recipe_step (recipe_step_id, recipe_id, section, position, body) VALUES
  (1, 1, NULL, 1, 'Preheat oven to 350°F.'),
  (2, 1, NULL, 2, 'In a large bowl, cream together the softened butter and sugar with a mixer on medium speed until light and fluffy (1-2 minutes). Mix in the egg and almond extract well.'),
  (3, 1, NULL, 3, 'Add the flour, baking soda, and salt to the wet ingredients and mix thoroughly to combine. Scrape the sides of the bowl as needed.'),
  (4, 1, NULL, 4, 'Scoop 3-4 tablespoons of dough, roll into a ball, and place on a baking sheet 2-3 inches apart. Bake until the edges just start to tan (about 9-12 minutes).'),
  (5, 1, NULL, 5, 'Let the cookies cool on the pan for 5 minutes, then transfer to a wire rack to finish cooling.'),
  (6, 1, NULL, 6, 'In a small bowl, make the icing by stirring together the powdered sugar, milk, and almond extract until smooth. Spread icing over the cooled cookies and top with a few sliced almonds.'),
  (7, 2, NULL, 1, 'Cut the chicken into filles and pound them'),
  (8, 2, NULL, 2, 'Coat the chicken in flour, then egg, then panko'),
  (9, 2, NULL, 3, 'Deep fry for a couple of minutes until crispy'),
  (10, 2, NULL, 4, 'For meal prep, place the un-fried chicken cutlets between layers of parchment paper and freeze. You can fry them from frozen later'),
  (11, 3, NULL, 1, 'Make the crumb topping: In a small bowl, whisk the flour, brown sugar, and cinnamon. Using a fork or a handheld mixer on low speed, mix in the butter until crumbly. Refrigerate the topping until the cookies are shaped.'),
  (12, 3, NULL, 2, 'Make the cookies: In a medium bowl, whisk the flour, cornstarch, baking powder, salt, and baking soda.'),
  (13, 3, NULL, 3, 'In a large bowl using a handheld or stand mixer fitted with the paddle, beat the butter, brown sugar, and granulated sugar on medium-high speed until the mixture is light and creamy, about 3 minutes. Add the egg, egg yolk, and vanilla and beat on high speed until combined, about 1 minute. Scrape down the sides of the bowl as needed. Add the flour mixture and beat on low speed until combined.'),
  (14, 3, NULL, 4, 'Cover the dough tightly and refrigerate it for at least 2 hours or up to 3 days.'),
  (15, 3, NULL, 5, 'Preheat the oven to 350°F (177°C). Line baking sheets with parchment paper or silicone baking mats. If the dough has chilled for longer than 2 hours, let it sit at room temperature for about 30 minutes.'),
  (16, 3, NULL, 6, 'Scoop and roll the chilled cookie dough into balls, about a scant 1½ tablespoons (30g) each. Using your fingers and thumbs, pinch and press a large indent in the center of the dough ball until it resembles a shallow bowl (1). Use the "bowl" of dough to scoop a generous amount of cold crumb topping to fill the cookie (2). Arrange them 3 inches apart on the prepared baking sheets (3).'),
  (17, 3, NULL, 7, 'Bake for 12 to 14 minutes or until the edges of the cookies are very lightly browned and set. Cool the cookies on the baking sheet for 10 minutes before transferring to a cooling rack to cool completely before icing.'),
  (18, 3, NULL, 8, 'Make the icing: In a small bowl, whisk the powdered sugar, 1 tablespoon milk, and vanilla. Add another tablespoon of milk to thin it out, if desired. Drizzle over the cooled cookies. The icing will set after about 2 hours. Store covered tightly at room temperature for up to 2 days or in the refrigerator for up to 1 week.'),
  (19, 4, NULL, 1, 'Bring a large pot of lightly salted water to a boil. Add fettuccine pasta and cook for 8 to 10 minutes or until al dente; drain.'),
  (20, 4, NULL, 2, 'Melt butter into cream in a large saucepan over low heat; add salt, pepper, and garlic salt.'),
  (21, 4, NULL, 3, 'Increase the heat to medium; stir in grated Romano and Parmesan cheese until melted and sauce has thickened.'),
  (22, 4, NULL, 4, 'Add cooked pasta to sauce and toss until thoroughly coated; serve immediately.'),
  (23, 5, NULL, 1, 'Boil pasta in salted water (think ocean) and 2Tbs. Olive oil according to time directions.  Drain return to hot pot. Add egg, cook and stir. Add butter and remaining olive oil. Add Parmesan cheese. Add garlic salt to taste. Parsley (optional).'),
  (24, 9, 'Make the Dough', 1, 'In the bowl of a stand mixer, combine the warm milk, yeast, and 1 teaspoon of the sugar. Let sit for 5–10 minutes until foamy.'),
  (25, 9, 'Make the Dough', 2, 'Add the remaining sugar, melted butter, eggs, and vanilla extract. Whisk to combine.'),
  (26, 9, 'Make the Dough', 3, 'Add 2 3/4 cups of flour and the salt. Using the dough hook attachment, mix on low speed until a soft dough forms.'),
  (27, 9, 'Make the Dough', 4, 'Knead on medium-low speed for 5–7 minutes (or knead by hand on a lightly floured surface) until smooth and elastic. If too sticky, add the remaining 1/4 cup of flour 1 tablespoon at a time.'),
  (28, 9, 'Make the Dough', 5, 'Shape the dough into a ball and place it in an oiled bowl, turning once to grease the top. Cover with plastic wrap or a clean towel and let rise in a warm place until doubled in size, about 1 hour.'),
  (29, 9, 'Prepare the Filling & Shape', 6, 'Butter and lightly flour a 9x5-inch loaf pan.'),
  (30, 9, 'Prepare the Filling & Shape', 7, 'In a small bowl, rub the orange zest into the granulated sugar and brown sugar using your fingers until fragrant. Stir in the cinnamon.'),
  (31, 9, 'Prepare the Filling & Shape', 8, 'Punch down the dough and turn it out onto a lightly floured surface. Roll into approximately a 12x20-inch rectangle.'),
  (32, 9, 'Prepare the Filling & Shape', 9, 'Brush the surface evenly with the 4 tablespoons of melted butter, then sprinkle the orange-cinnamon sugar evenly over the butter.'),
  (33, 9, 'Prepare the Filling & Shape', 10, 'Cut the dough lengthwise into 6 equal strips. Stack the strips on top of each other, then cut the stack into 6 equal squares/rectangles (yielding 6 stacks of layered squares).'),
  (34, 9, 'Prepare the Filling & Shape', 11, 'Layer the dough squares cut-side up (like index cards in a file box) into the prepared loaf pan.'),
  (35, 9, 'Prepare the Filling & Shape', 12, 'Cover loosely and let rise again for 30–45 minutes, until puffy.'),
  (36, 9, 'Bake & Glaze', 13, 'Preheat your oven to 350°F (175°C).'),
  (37, 9, 'Bake & Glaze', 14, 'Bake the loaf for 30–35 minutes, until golden brown on top and baked through the center. (If the top browns too quickly, tent loosely with aluminum foil for the last 10 minutes).'),
  (38, 9, 'Bake & Glaze', 15, 'Let the bread cool in the pan on a wire rack for 10–15 minutes.'),
  (39, 9, 'Bake & Glaze', 16, 'Meanwhile, whisk together the powdered sugar, orange juice, orange zest, and vanilla extract in a small bowl until smooth.'),
  (40, 9, 'Bake & Glaze', 17, 'Drizzle the glaze generously over the warm bread and serve warm.'),
  (41, 10, NULL, 1, 'Whisk flour and baking soda together in a medium bowl. Set aside.'),
  (42, 10, NULL, 2, 'Beat together butter, peanut butter, brown sugar, ⅓ cup of the granulated sugar, and salt until well-combined and slightly lighter in color.'),
  (43, 10, NULL, 3, 'Beat in the egg and vanilla. Then add the flour mixture and mix until just combined.'),
  (44, 10, NULL, 4, 'If the dough is too sticky to roll, refrigerate for 15 minutes.'),
  (45, 10, NULL, 5, 'Put the remaining ⅓ cup granulated sugar in a bowl. Roll dough into balls, roll in the sugar, and arrange on a baking sheet.'),
  (46, 10, NULL, 6, 'Bake at 375°F for 8–10 minutes, until they look puffy and crackled and are just starting to brown on the bottom.'),
  (47, 10, NULL, 7, 'Immediately press one chocolate kiss on top of each cookie and allow to cool to doneness.'),
  (48, 11, 'Make the Salted Caramel', 1, 'Heat granulated sugar in a medium saucepan over medium-low heat, stirring constantly with a heatproof spatula or wooden spoon. The sugar will form clumps and eventually melt into a thick amber-colored liquid (keep a close eye so it doesn''t burn).'),
  (49, 11, 'Make the Salted Caramel', 2, 'Once the sugar is completely melted, carefully add the cubed butter. Whisk vigorously until the butter is fully melted and incorporated (the mixture will bubble vigorously).'),
  (50, 11, 'Make the Salted Caramel', 3, 'Slowly drizzle in the heavy cream while continuing to whisk. Allow the mixture to boil for 1 minute.'),
  (51, 11, 'Make the Salted Caramel', 4, 'Remove from heat and stir in the 1 tsp flaky sea salt. Set aside to cool slightly while you make the brownie batter.'),
  (52, 11, 'Make the Brownie Batter', 5, 'Preheat your oven to 350°F (175°C). Line a 9x9-inch metal baking pan with parchment paper, leaving an overhang on the sides for easy removal.'),
  (53, 11, 'Make the Brownie Batter', 6, 'In a heatproof bowl set over a pot of simmering water (or in 30-second bursts in the microwave), melt the butter and chopped chocolate together until smooth and glossy. Set aside to cool slightly.'),
  (54, 11, 'Make the Brownie Batter', 7, 'In a large bowl, whisk together the granulated sugar, brown sugar, eggs, and vanilla extract vigorously for 1–2 minutes until pale, frothy, and slightly thickened (this creates the crinkly top).'),
  (55, 11, 'Make the Brownie Batter', 8, 'Slowly pour the melted chocolate-butter mixture into the egg mixture, whisking constantly until combined.'),
  (56, 11, 'Make the Brownie Batter', 9, 'Sift in the flour, cocoa powder, and salt. Gently fold with a rubber spatula just until no dry flour streaks remain (do not overmix).'),
  (57, 11, 'Assemble & Bake', 10, 'Pour roughly half of the brownie batter into the prepared baking pan and smooth into an even layer.'),
  (58, 11, 'Assemble & Bake', 11, 'Drizzle about 1/3 to 1/2 cup of the salted caramel sauce evenly over the batter layer.'),
  (59, 11, 'Assemble & Bake', 12, 'Pour the remaining brownie batter over the top, gently smoothing it out.'),
  (60, 11, 'Assemble & Bake', 13, 'Spoon additional tablespoons of caramel over the top layer and use a butter knife or toothpick to gently swirl the caramel into the top batter. (Save any leftover caramel for serving).'),
  (61, 11, 'Assemble & Bake', 14, 'Bake at 350°F (175°C) for 32–38 minutes, until the edges are set and a toothpick inserted into the center comes out with moist, fudgy crumbs (not wet batter).'),
  (62, 11, 'Assemble & Bake', 15, 'Remove from the oven and immediately sprinkle generously with flaky sea salt.'),
  (63, 11, 'Assemble & Bake', 16, 'Allow the brownies to cool completely in the pan at room temperature before slicing for clean cuts.'),
  (64, 12, NULL, 1, 'Peel potatos'),
  (65, 12, NULL, 2, 'Blend half an onion, half bell pepper, spinach, and a lot of cilantro (with a little water)'),
  (66, 12, NULL, 3, 'Put the mixture in a large pot. Put a lid on the pot and turn the heat to medium. Let the mixture evaporate and collect'),
  (67, 12, NULL, 4, 'Add chicken. Cook for 5 min total and flip to cook both sides'),
  (68, 12, NULL, 5, 'Add water'),
  (69, 12, NULL, 6, 'Salt'),
  (70, 12, NULL, 7, 'Taste'),
  (71, 12, NULL, 8, 'Potatos, peas, carrots, corns, veggies, etc'),
  (72, 12, NULL, 9, 'Cook some more (40 min - 1 hr)'),
  (73, 12, NULL, 10, 'Serve with rice and optionally beans'),
  (74, 14, NULL, 1, 'Test the Oil: Add the oil and 3–4 "test" kernels to the pot. Cover with the lid and place over medium-high heat.'),
  (75, 14, NULL, 2, 'Wait for the Test Kernels: When the test kernels pop, the oil is at the ideal temperature. Remove the popped test kernels with a spoon or tongs.'),
  (76, 14, NULL, 3, 'Even Heating: Add the remaining 1/3 cup of kernels in a single, even layer. Cover the pot and immediately remove it from the heat for 30 seconds (this brings all kernels up to near-popping temperature so they pop at the same time and don''t burn).'),
  (77, 14, NULL, 4, 'Pop the Corn: Return the pot to medium-high heat. Keep the lid slightly cracked/ajar to allow steam to escape (this keeps the popcorn light and crisp rather than chewy). Shake the pot gently back and forth over the burner while the corn pops.'),
  (78, 14, NULL, 5, 'Remove from Heat: Once the popping slows to roughly 2–3 seconds between pops, remove the pot immediately from the heat. Remove the lid and dump the popcorn into your serving bowl right away to prevent trapped steam or scorching at the bottom.'),
  (79, 14, NULL, 6, 'Season and Serve: Drizzle warm melted butter over the top and toss thoroughly. Sprinkle fine salt and desired seasonings, tossing gently until evenly coated.'),
  (80, 15, NULL, 1, 'Make the katsu as in Celeste''s Chicken Katsu.'),
  (81, 15, NULL, 2, 'Saute the onion, carrot, and potato, cover with water, and simmer until tender.'),
  (82, 15, NULL, 3, 'Turn off the heat and dissolve the curry roux, then simmer until thick.'),
  (83, 15, NULL, 4, 'Slice the katsu and serve over rice with the curry.'),
  (84, 16, NULL, 1, 'Cook the pasta in salted water and reserve a cup of the water.'),
  (85, 16, NULL, 2, 'Melt the butter, cook the garlic, then whisk in the flour and milk until thick.'),
  (86, 16, NULL, 3, 'Stir in the Parmesan and toss with the pasta, loosening with pasta water.'),
  (87, 17, NULL, 1, 'Brown the turkey in the oil, then add the onion, bell pepper, and garlic and cook until soft.'),
  (88, 17, NULL, 2, 'Stir in the chili powder and cumin for one minute.'),
  (89, 17, NULL, 3, 'Add the tomatoes and beans, then simmer 30 minutes, stirring now and then.'),
  (90, 17, NULL, 4, 'Season with salt and serve with cheese and sour cream.'),
  (91, 18, NULL, 1, 'Preheat the oven to 350°F and grease a 9x5-inch loaf pan.'),
  (92, 18, NULL, 2, 'Stir the melted butter into the mashed bananas, then mix in the sugar, egg, and vanilla.'),
  (93, 18, NULL, 3, 'Sprinkle the baking soda and salt over the mixture, then fold in the flour until just combined.'),
  (94, 18, NULL, 4, 'Pour into the pan and bake 55 to 65 minutes, until a toothpick comes out clean.'),
  (95, 19, NULL, 1, 'Brown the butter and let it cool until it is soft but not liquid.'),
  (96, 19, NULL, 2, 'Beat the butter and sugar, then add the eggs.'),
  (97, 19, NULL, 3, 'Mix in the dry ingredients, roll into balls, and coat in cinnamon sugar.'),
  (98, 20, NULL, 1, 'Preheat oven to 350°F. Press the butter, sugar, and flour together into a 9x13-inch pan and bake 15 to 20 minutes.'),
  (99, 20, NULL, 2, 'Whisk the eggs, sugar, flour, lemon juice, and zest until smooth.'),
  (100, 20, NULL, 3, 'Pour over the hot crust and bake 20 minutes more, until set.'),
  (101, 20, NULL, 4, 'Cool completely, chill, then dust with powdered sugar and cut into bars.'),
  (102, 21, NULL, 1, 'Cook the onion in oil until golden, then add the garlic and ginger.'),
  (103, 21, NULL, 2, 'Stir in the garam masala and cumin for 30 seconds.'),
  (104, 21, NULL, 3, 'Add the tomatoes and chickpeas and simmer 20 minutes, mashing a few chickpeas to thicken.'),
  (105, 21, NULL, 4, 'Season with salt and serve over rice with cilantro.'),
  (106, 22, NULL, 1, 'Blend everything until smooth.'),
  (107, 22, NULL, 2, 'Taste, add more sugar if needed, and serve cold.'),
  (108, 23, NULL, 1, 'Mash the avocados with the lime juice and salt.'),
  (109, 23, NULL, 2, 'Fold in the onion, jalapeno, cilantro, and tomato.'),
  (110, 23, NULL, 3, 'Taste, adjust the salt and lime, and serve right away.'),
  (111, 24, NULL, 1, 'Soak the noodles in warm water until bendy, then drain.'),
  (112, 24, NULL, 2, 'Whisk the tamarind, fish sauce, and sugar for the sauce.'),
  (113, 24, NULL, 3, 'Stir-fry the garlic in oil, push aside, and scramble the eggs.'),
  (114, 24, NULL, 4, 'Add the noodles and sauce and toss until absorbed, then add the sprouts.'),
  (115, 24, NULL, 5, 'Top with peanuts and serve with lime.');
