INSERT INTO recipe_note (recipe_note_id, recipe_id, author_id, title, body, created_at) VALUES
  (1, 1, 1, NULL, 'I usually make a little more icing than the recipe', '2026-06-18'),
  (2, 4, 1, NULL, 'I usually double the cheese', '2026-06-27'),
  (3, 4, 1, NULL, 'you can make it without the cream by melting the butter, tossing the pasta in the butter, then adding the cheese to the pasta', '2026-06-27'),
  (4, 6, 1, NULL, 'they with more sugar next time', '2026-07-03'),
  (5, 6, 1, NULL, 'did a double batch of dough. Used 10 eggs, 1lb sausage, 2 packs of bacon, two cups of cheese, and two jalapeños', '2026-07-03'),
  (6, 7, 1, NULL, 'Use extra cream cheese for the filling', '2026-07-06'),
  (7, 7, 1, NULL, 'Melt the butter s little bit so the cookies spread and are bigger and thinner (if you want sandwich cookies)', '2026-07-06'),
  (8, 7, 1, NULL, 'We preferred the taste with old fashioned oats over quick oats', '2026-07-06'),
  (9, 8, 1, 'Meal Prep Advice from Gemini', 'Freeze the chicken after frying and without the sauce or onions.
